style.css:
@-moz-document domain("thenkiri.com") {
/* 1. Absolute Black Base Grid */
    html, body, #outer-wrap, #wrap, #main, .site-main {
        background-color: #000000 !important;
        color: #e6e6e6 !important;
    }

    /* 2. Top Navigation Bar */
    #site-header, 
    .site-header-inner, 
    #site-header-wrap,
    .oceanwp-mobile-menu-icon,
    #site-navigation-wrap {
        background-color: #000000 !important;
        border-bottom: 1px solid #222222 !important;
    }

    /* Navigation Links */
    #site-navigation ul li a, 
    .site-title a, 
    .oceanwp-mobile-menu-icon a {
        color: #ffffff !important;
    }

    #site-navigation ul li a:hover {
        color: #00f2fe !important;
    }

    /* 3. Media Grid Containers & Listing Blocks */
    .elementor-widget-container,
    .elementor-card,
    .blog-entry-inner,
    .thumbnail-inner,
    article.post,
    .wp-block-group {
        background-color: #000000 !important;
        border: 1px solid #222222 !important;
        border-radius: 6px !important;
        box-shadow: none !important;
    }

    /* Dynamic Item Headers */
    h2.entry-title a, 
    h3.entry-title a, 
    .elementor-heading-title, 
    h1, h2, h3, h4, h5, h6 {
        color: #ffffff !important;
        text-shadow: 0 0 1px rgba(255,255,255,0.1);
    }

    h2.entry-title a:hover, 
    h3.entry-title a:hover {
        color: #00f2fe !important;
    }

    /* Content descriptions, meta details, and body blocks */
    .entry-meta, .entry-meta span, .entry-content p, p, li {
        color: #b3b3b3 !important;
    }

    p a, li a {
        color: #00f2fe !important;
        text-decoration: underline !important;
    }

    /* 4. Action Target Buttons */
    .elementor-button,
    a.button,
    input[type="submit"],
    .btn,
    .load-more-pointer {
        background: linear-gradient(135deg, #00f2fe 0%, #4facfe 100%) !important;
        color: #000000 !important;
        font-weight: 700 !important;
        border: none !important;
        border-radius: 4px !important;
    }

    .elementor-button:hover,
    a.button:hover,
    input[type="submit"]:hover {
        background: #ffffff !important;
        color: #000000 !important;
    }

    /* 5. Deep Form Inputs & Search Blocks */
    input[type="text"],
    input[type="search"],
    textarea,
    .search-form input {
        background-color: #000000 !important;
        color: #ffffff !important;
        border: 1px solid #444444 !important;
        border-radius: 4px !important;
    }

    input:focus, 
    textarea:focus {
        border-color: #00f2fe !important;
        outline: 1px solid #00f2fe !important;
    }

    /* 6. Static / Sticky Notices */
    .notice, 
    .alert,
    div[class*="notice"],
    div[class*="warning"] {
        background-color: #000000 !important;
        border: 2px solid #ff3333 !important;
        color: #ff3333 !important;
        font-weight: bold !important;
    }

    /* 7. Footer Interface */
    #footer, 
    #footer-bottom,
    .footer-widgets {
        background-color: #000000 !important;
        border-top: 1px solid #222222 !important;
        color: #666666 !important;
    }

    #footer a, 
    #footer-bottom a {
        color: #a6a6a6 !important;
    }
}
